CREATE TABLE market_ingestion_runs(market_run_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL CHECK(status IN('RUNNING','SUCCEEDED','PARTIAL','FAILED')),securities_requested INTEGER NOT NULL,securities_succeeded INTEGER NOT NULL DEFAULT 0,records_processed INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,parser_version TEXT NOT NULL,error_details TEXT);
CREATE TABLE market_observations(observation_id TEXT PRIMARY KEY,security_id TEXT NOT NULL REFERENCES securities,trade_date TEXT NOT NULL,exchange_timestamp TEXT,source_timestamp TEXT NOT NULL,timezone TEXT NOT NULL,trading_session TEXT,auction_type TEXT,trade_type TEXT,open TEXT,high TEXT,low TEXT,close TEXT,last TEXT,individual_trade_price TEXT,share_volume TEXT,turnover_value TEXT,trade_count INTEGER,bid TEXT,ask TEXT,bid_size TEXT,ask_size TEXT,currency TEXT,source_id TEXT NOT NULL REFERENCES data_sources,document_id TEXT NOT NULL REFERENCES raw_documents,market_run_id TEXT NOT NULL REFERENCES market_ingestion_runs,series_type TEXT NOT NULL CHECK(series_type IN('RAW_OBSERVED','CORPORATE_ACTION_ADJUSTED','TOTAL_RETURN')),parser_version TEXT NOT NULL,payload_hash TEXT NOT NULL,first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,UNIQUE(security_id,trade_date,source_id,series_type,payload_hash),CHECK(open IS NULL OR CAST(open AS REAL)>0),CHECK(high IS NULL OR CAST(high AS REAL)>0),CHECK(low IS NULL OR CAST(low AS REAL)>0),CHECK(close IS NULL OR CAST(close AS REAL)>0),CHECK(share_volume IS NULL OR CAST(share_volume AS REAL)>=0),CHECK(turnover_value IS NULL OR CAST(turnover_value AS REAL)>=0),CHECK(trade_count IS NULL OR trade_count>=0));
CREATE INDEX market_history ON market_observations(security_id,trade_date,series_type);
CREATE TABLE market_quality_flags(flag_id TEXT PRIMARY KEY,security_id TEXT NOT NULL REFERENCES securities,trade_date TEXT,flag_type TEXT NOT NULL CHECK(flag_type IN('STALE_PRICE','VERY_STALE_PRICE','LOW_OBSERVATION_COUNT','ABNORMAL_PRICE_MOVE','SINGLE_TRADE_MOVE','MISSING_VOLUME','POSSIBLE_UNIT_CHANGE','POSSIBLE_CORPORATE_ACTION','DUPLICATE_RECORD','IMPOSSIBLE_PRICE')),severity TEXT NOT NULL CHECK(severity IN('INFO','WARNING','ERROR','CRITICAL')),details TEXT NOT NULL,market_run_id TEXT NOT NULL REFERENCES market_ingestion_runs,created_at TEXT NOT NULL,UNIQUE(security_id,trade_date,flag_type,market_run_id));
